<script setup lang="ts">import{createInventoryCsv,createInventoryJson}from"@/domain/library/inventoryReport";import type{InventoryItemRecord,InventoryRecord}from"@/domain/library/inventoryRecords";defineProps<{open:boolean;inventory:InventoryRecord;items:InventoryItemRecord[]}>();const emit=defineEmits<{close:[]}>();function download(content:string,name:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}</script><template><Teleport to="body"><div v-if="open" class="dialog-backdrop"><section class="dialog-panel inventory-report-dialog" role="dialog" aria-modal="true" aria-labelledby="inventory-report-title"><div class="dialog-header"><div><p class="eyebrow">Relatório final</p><h2 id="inventory-report-title">{{inventory.nome}}</h2></div><button class="icon-button" type="button" aria-label="Fechar" @click="emit('close')">×</button></div><p>{{inventory.total_verificado||0}} de {{inventory.total_previsto||0}} exemplares verificados.</p><div class="form-actions"><button class="button button-secondary" type="button" @click="download(createInventoryCsv(inventory,items),'inventario.csv','text/csv;charset=utf-8')">Exportar CSV</button><button class="button button-secondary" type="button" @click="download(createInventoryJson(inventory,items),'inventario.json','application/json')">Exportar JSON</button></div></section></div></Teleport></template>
